// Probe (round-1 R3-1a): old account-lock code reads a ledger DIRECTORY, so a
// tombstone does not fence it. Fence instead with a final generation whose
// holder is PID 1 (init) with its real start time: production
// tryAcquireAccountLock must see a live holder forever and refuse.
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
const HERE = path.dirname(fileURLToPath(import.meta.url));
const m = await import('/home/vantt/projects/forgentX/src/runner/dispatch/provider-capacity.mjs');
const st = (pid) => { const s = fs.readFileSync(`/proc/${pid}/stat`, 'utf8'); return s.slice(s.lastIndexOf(')') + 2).split(' ')[19]; };
const runtimeDir = fs.mkdtempSync(path.join(HERE, 'run-fence-'));
const out = {};
const h = m.tryAcquireAccountLock({ runtimeDir, provider: 'openai', accountId: 'acc1' });
out.v1AcquireBeforeFence = h ? 'acquired' : 'held'; h?.release?.();
// find the ledger dir the production code used
const lockDir = (function find(d) { for (const e of fs.readdirSync(d, { withFileTypes: true })) { const p = path.join(d, e.name); if (e.isDirectory()) { if (e.name === 'lock') return p; const r = find(p); if (r) return r; } } return null; })(runtimeDir);
const gens = fs.readdirSync(lockDir).filter((n) => /^\d{10}\.json$/.test(n)).sort();
const next = String(Number(gens.at(-1)?.slice(0, 10) ?? 0) + 1).padStart(10, '0');
fs.writeFileSync(path.join(lockDir, `${next}.json`), JSON.stringify({ holder: { pid: 1, processStartTime: st(1) }, fence: { movedTo: 'kernel lock', at: new Date().toISOString() } }));
const h2 = m.tryAcquireAccountLock({ runtimeDir, provider: 'openai', accountId: 'acc1' });
out.v1AcquireAfterFence = h2 ? 'acquired' : 'held';
h2?.release?.();
out.ledgerFiles = fs.readdirSync(lockDir);
fs.writeFileSync(path.join(HERE, 'probe-ledger-fence-generation-results.json'), JSON.stringify(out, null, 1));
console.log(JSON.stringify(out));

