// Probe B2 (physical launch floor): a directory "tombstone" at a v1 lock path.
// Runs the REAL v1 lock code (main HEAD, and the W1' branch copy) against it:
// acquire, inspect, release, releaseIfOwn, forceReclaim. Every call must fail
// closed (throw or report held/ambiguous) and leave the tombstone in place.
// Run: node probe-tombstone.mjs
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
const HERE = path.dirname(fileURLToPath(import.meta.url));
const variants = {
  'main-HEAD': '/home/vantt/projects/forgentX/src/runner/main-checkout-lock.mjs',
  'W1-branch': path.join(HERE, 'v1-w1/src/runner/main-checkout-lock.mjs'),
};
const out = [];
for (const [name, mod] of Object.entries(variants)) {
  const m = await import(mod);
  const dir = fs.mkdtempSync(path.join(HERE, `run-tomb-${name}-`));
  const lockPath = path.join(dir, 'main-checkout.lock');
  fs.mkdirSync(lockPath); fs.writeFileSync(path.join(lockPath, 'TOMBSTONE'), JSON.stringify({ v: 3, movedTo: 'runtime/locks/main-checkout/' }));
  const call = (label, fn) => { try { const r = fn(); out.push({ variant: name, call: label, returned: r?.status ?? r }); } catch (e) { out.push({ variant: name, call: label, threw: e.code || e.message }); } };
  call('acquire(pid)', () => m.acquireMainCheckoutLock(dir, { identity: process.pid, ttlMs: 1000 }));
  call('acquire(session string)', () => m.acquireMainCheckoutLock(dir, { identity: 'sess-x', ttlMs: 1000 }));
  if (m.inspectMainCheckoutLock) call('inspect', () => m.inspectMainCheckoutLock(dir));
  call('release', () => m.releaseMainCheckoutLock(dir));
  call('releaseIfOwn', () => m.releaseMainCheckoutLockIfOwn(dir, process.pid));
  call('forceReclaimAmbiguous', () => m.forceReclaimAmbiguousLock(dir));
  out.push({ variant: name, tombstoneStillThere: fs.statSync(lockPath).isDirectory() && fs.existsSync(path.join(lockPath, 'TOMBSTONE')) });
}
fs.writeFileSync(path.join(HERE, 'probe-tombstone-results.json'), JSON.stringify(out, null, 1));
for (const o of out) console.log(JSON.stringify(o));
